content:
:root {
  --bg-primary: #f8fafc;
  --bg-card: #ffffff;
  --text-main: #0f172a;
  --text-sub: #64748b;
  --text-muted: #94a3b8;
  --primary: #3b82f6;
  --primary-hover: #2563eb;
  --primary-light: #eff6ff;
  --border-color: #e2e8f0;
  --danger: #ef4444;
  --danger-hover: #dc2626;
  --danger-light: #fef2f2;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* アプリ全体のコンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  min-height: 100vh;
}

/* ヘッダー */
.app-header {
  margin-bottom: 24px;
  text-align: center;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
}

.app-subtitle {
  font-size: 0.95rem;
  color: var(--text-sub);
  margin-top: 4px;
}

/* 合計金額バナー */
.total-banner {
  background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
  color: #ffffff;
  border-radius: var(--radius-lg);
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-md);
  margin-bottom: 24px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.total-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: #cbd5e1;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.total-value {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #ffffff;
}

/* ダッシュボードグリッドレイアウト */
.dashboard-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
  align-items: start;
}

@media (min-width: 900px) {
  .dashboard-grid {
    grid-template-columns: 1.15fr 0.85fr;
  }
}

/* グラフカード */
.chart-card {
  background-color: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.chart-card-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 12px;
}

.chart-wrapper {
  position: relative;
  width: 100%;
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.center-info {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  pointer-events: none;
  background-color: rgba(255, 255, 255, 0.95);
  border-radius: var(--radius-full);
  width: 128px;
  height: 128px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-color);
  z-index: 10;
}

.center-info-label {
  font-size: 0.825rem;
  color: var(--text-sub);
  font-weight: 600;
  max-width: 100px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.center-info-value {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--text-main);
  margin-top: 2px;
}

/* 項目詳細カード */
.detail-card {
  background-color: #f1f5f9;
  border-radius: var(--radius-md);
  padding: 20px;
  border: 1px solid #cbd5e1;
  display: flex;
  flex-direction: column;
  gap: 16px;
  animation: fadeIn 0.2s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.detail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.detail-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.detail-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
}

.detail-amount {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text-main);
}

.detail-percentage {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--primary);
  background-color: var(--primary-light);
  padding: 4px 10px;
  border-radius: var(--radius-full);
}

.detail-edit-form {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.detail-input {
  flex: 1;
  min-width: 140px;
  padding: 10px 14px;
  font-size: 0.95rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: var(--bg-card);
  color: var(--text-main);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.detail-input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.detail-save-btn {
  padding: 10px 18px;
  background-color: var(--primary);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.15s, transform 0.05s;
  min-height: 44px;
}

.detail-save-btn:hover {
  background-color: var(--primary-hover);
}

.detail-save-btn:active {
  transform: translateY(1px);
}

.detail-close-btn {
  background: none;
  border: none;
  color: var(--text-sub);
  font-size: 1.25rem;
  line-height: 1;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  transition: color 0.15s, background-color 0.15s;
}

.detail-close-btn:hover {
  color: var(--text-main);
  background-color: rgba(0, 0, 0, 0.05);
}

/* リストカード */
.list-card {
  background-color: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.list-card-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 12px;
}

/* 支出項目リスト */
.expense-items-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 440px;
  overflow-y: auto;
  padding-right: 4px;
}

.expense-item-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  background-color: var(--bg-card);
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  user-select: none;
}

.expense-item-row:hover {
  border-color: #cbd5e1;
  background-color: #f8fafc;
  transform: translateX(2px);
}

.expense-item-row.active {
  background-color: #eff6ff;
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary);
}

.expense-item-color-bar {
  width: 6px;
  height: 36px;
  border-radius: var(--radius-full);
  flex-shrink: 0;
}

.expense-item-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.expense-item-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-main);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.expense-item-percent {
  font-size: 0.8rem;
  color: var(--text-sub);
}

.expense-item-amount {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);
  text-align: right;
  white-space: nowrap;
}

.expense-item-delete-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 1.1rem;
  padding: 6px 8px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s;
  min-height: 36px;
  min-width: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.expense-item-delete-btn:hover {
  color: var(--danger);
  background-color: var(--danger-light);
}

/* 支出項目追加フォーム */
.add-item-form {
  border-top: 1px dashed var(--border-color);
  padding-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.form-input-group {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.form-input {
  flex: 1;
  min-width: 120px;
  padding: 10px 12px;
  font-size: 0.9rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: #f8fafc;
  color: var(--text-main);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.form-input:focus {
  background-color: var(--bg-card);
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.form-color-picker {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  width: 44px;
  height: 42px;
  padding: 2px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  cursor: pointer;
  background-color: #f8fafc;
}

.form-color-picker::-webkit-color-swatch-wrapper {
  padding: 0;
}

.form-color-picker::-webkit-color-swatch {
  border: none;
  border-radius: 4px;
}

.form-add-btn {
  width: 100%;
  padding: 10px 16px;
  background-color: var(--primary);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.15s, transform 0.05s;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.form-add-btn:hover {
  background-color: var(--primary-hover);
}

.form-add-btn:active {
  transform: translateY(1px);
}

export interface ExpenseItem {
  id: string;
  name: string;
  amount: number;
  color: string;
  icon: string;
}

export interface ExpenseSummary {
  totalAmount: number;
  itemCount: number;
}

export interface ExpensePieChartProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelectItem: (id: string) => void;
}

export interface ExpenseDetailProps {
  selectedItem: ExpenseItem | null;
  totalAmount: number;
  onUpdateAmount: (id: string, amount: number) => void;
  onClose: () => void;
}

export interface ExpenseListProps {
  items: ExpenseItem[];
  selectedId: string | null;
  totalAmount: number;
  onSelectItem: (id: string) => void;
  onAddItem: (item: Omit<ExpenseItem, 'id'>) => void;
  onDeleteItem: (id: string) => void;
}

import { useMemo } from 'react';
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip } from 'recharts';
import { ExpensePieChartProps } from '../types';

interface ChartDataItem {
  id: string;
  name: string;
  value: number;
  color: string;
  icon: string;
}

const ExpensePieChart = ({
  items = [],
  selectedId = null,
  onSelectItem,
}: ExpensePieChartProps) => {
  const chartData: ChartDataItem[] = useMemo(() => {
    return items
      .filter((item) => item.amount > 0)
      .map((item) => ({
        id: item.id,
        name: item.name,
        value: item.amount,
        color: item.color,
        icon: item.icon,
      }));
  }, [items]);

  const totalAmount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.amount, 0);
  }, [items]);

  const selectedItem = useMemo(() => {
    if (!selectedId) return null;
    return items.find((item) => item.id === selectedId) || null;
  }, [items, selectedId]);

  const selectedPercentage = useMemo(() => {
    if (!selectedItem || totalAmount === 0) return 0;
    return Math.round((selectedItem.amount / totalAmount) * 100);
  }, [selectedItem, totalAmount]);

  const handlePieClick = (data: { id?: string }) => {
    if (data && data.id && onSelectItem) {
      onSelectItem(data.id);
    }
  };

  return (
    <div className="chart-card">
      <h2 className="chart-card-title">支出割合チャート</h2>
      <div className="chart-wrapper">
        <ResponsiveContainer width="100%" height={320}>
          <PieChart>
            <Tooltip
              formatter={(value: number) => [`¥${value.toLocaleString()}`, '金額']}
              contentStyle={{
                backgroundColor: '#ffffff',
                borderColor: '#e2e8f0',
                borderRadius: '8px',
                fontSize: '13px',
                boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.08)',
              }}
            />
            <Pie
              data={chartData}
              dataKey="value"
              nameKey="name"
              cx="50%"
              cy="50%"
              innerRadius={72}
              outerRadius={110}
              paddingAngle={3}
              onClick={handlePieClick}
              cursor="pointer"
            >
              {chartData.map((entry) => {
                const isSelected = entry.id === selectedId;
                return (
                  <Cell
                    key={`cell-${entry.id}`}
                    fill={entry.color}
                    stroke={isSelected ? '#0f172a' : '#ffffff'}
                    strokeWidth={isSelected ? 3 : 1}
                    opacity={selectedId ? (isSelected ? 1 : 0.45) : 1}
                  />
                );
              })}
            </Pie>
          </PieChart>
        </ResponsiveContainer>

        <div className="center-info">
          {selectedItem ? (
            <>
              <span className="center-info-label" title={selectedItem.name}>
                {selectedItem.icon} {selectedItem.name}
              </span>
              <span className="center-info-value">{selectedPercentage}%</span>
            </>
          ) : (
            <>
              <span className="center-info-label">合計支出</span>
              <span className="center-info-value">
                ¥{totalAmount >= 1000000
                  ? `${Math.round(totalAmount / 10000)}万`
                  : totalAmount.toLocaleString()}
              </span>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default ExpensePieChart;

import { useState, useEffect, FormEvent } from 'react';
import { ExpenseDetailProps } from '../types';

const ExpenseDetail = ({
  selectedItem = null,
  totalAmount = 0,
  onUpdateAmount,
  onClose,
}: ExpenseDetailProps) => {
  const [editAmount, setEditAmount] = useState<string>('');

  useEffect(() => {
    if (selectedItem) {
      setEditAmount(selectedItem.amount.toString());
    } else {
      setEditAmount('');
    }
  }, [selectedItem]);

  if (!selectedItem) {
    return null;
  }

  const percentage =
    totalAmount > 0
      ? ((selectedItem.amount / totalAmount) * 100).toFixed(1)
      : '0.0';

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const num = parseInt(editAmount, 10);
    if (!isNaN(num) && num >= 0 && onUpdateAmount) {
      onUpdateAmount(selectedItem.id, num);
    }
  };

  return (
    <div className="detail-card">
      <div className="detail-header">
        <div className="detail-badge">
          <span style={{ fontSize: '1.4rem' }}>{selectedItem.icon}</span>
          <span className="detail-title">{selectedItem.name}</span>
        </div>
        <button
          type="button"
          className="detail-close-btn"
          onClick={() => onClose?.()}
          aria-label="詳細を閉じる"
        >
          ×
        </button>
      </div>

      <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px', flexWrap: 'wrap' }}>
        <span className="detail-amount">¥{selectedItem.amount.toLocaleString()}</span>
        <span className="detail-percentage">全体比 {percentage}%</span>
      </div>

      <form className="detail-edit-form" onSubmit={handleSubmit}>
        <input
          type="number"
          min="0"
          step="100"
          className="detail-input"
          value={editAmount}
          onChange={(e) => setEditAmount(e.target.value)}
          placeholder="金額を変更"
          aria-label="金額"
          required
        />
        <button type="submit" className="detail-save-btn">
          金額を更新
        </button>
      </form>
    </div>
  );
};

export default ExpenseDetail;

import { useState, FormEvent } from 'react';
import { ExpenseListProps } from '../types';

const PRESET_ICONS = ['🍽️', '🏠', '⚡', '📱', '🧴', '🎉', '💊', '📦', '🚗', '📚', '☕', '🐾'];

const ExpenseList = ({
  items = [],
  selectedId = null,
  totalAmount = 0,
  onSelectItem,
  onAddItem,
  onDeleteItem,
}: ExpenseListProps) => {
  const [name, setName] = useState('');
  const [amount, setAmount] = useState('');
  const [color, setColor] = useState('#3b82f6');
  const [icon, setIcon] = useState('📦');

  const handleAddSubmit = (e: FormEvent) => {
    e.preventDefault();
    const parsedAmount = parseInt(amount, 10);
    if (!name.trim() || isNaN(parsedAmount) || parsedAmount < 0) {
      return;
    }

    if (onAddItem) {
      onAddItem({
        name: name.trim(),
        amount: parsedAmount,
        color,
        icon,
      });
    }

    setName('');
    setAmount('');
  };

  return (
    <div className="list-card">
      <h2 className="list-card-title">支出内訳一覧</h2>

      <div className="expense-items-list">
        {items.map((item) => {
          const isSelected = item.id === selectedId;
          const percent =
            totalAmount > 0
              ? ((item.amount / totalAmount) * 100).toFixed(1)
              : '0.0';

          return (
            <div
              key={item.id}
              className={isSelected ? 'expense-item-row active' : 'expense-item-row'}
              onClick={() => onSelectItem?.(item.id)}
              role="button"
              tabIndex={0}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  onSelectItem?.(item.id);
                }
              }}
            >
              <div
                className="expense-item-color-bar"
                style={{ backgroundColor: item.color }}
              />
              <span style={{ fontSize: '1.25rem' }}>{item.icon}</span>
              <div className="expense-item-info">
                <span className="expense-item-name">{item.name}</span>
                <span className="expense-item-percent">{percent}%</span>
              </div>
              <span className="expense-item-amount">
                ¥{item.amount.toLocaleString()}
              </span>
              <button
                type="button"
                className="expense-item-delete-btn"
                title="項目を削除"
                aria-label={`${item.name}を削除`}
                onClick={(e) => {
                  e.stopPropagation();
                  onDeleteItem?.(item.id);
                }}
              >
                ✕
              </button>
            </div>
          );
        })}
      </div>

      <form className="add-item-form" onSubmit={handleAddSubmit}>
        <div className="form-input-group">
          <input
            type="text"
            className="form-input"
            placeholder="項目名 (例: カフェ代)"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            maxLength={20}
          />
          <input
            type="number"
            min="0"
            step="100"
            className="form-input"
            placeholder="金額 (円)"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            required
          />
        </div>

        <div className="form-input-group" style={{ alignItems: 'center' }}>
          <select
            className="form-input"
            value={icon}
            onChange={(e) => setIcon(e.target.value)}
            style={{ maxWidth: '80px', textAlign: 'center', fontSize: '1.1rem' }}
            aria-label="アイコン選択"
          >
            {PRESET_ICONS.map((i) => (
              <option key={i} value={i}>
                {i}
              </option>
            ))}
          </select>
          <input
            type="color"
            className="form-color-picker"
            value={color}
            onChange={(e) => setColor(e.target.value)}
            title="カラーを選択"
            aria-label="カラー"
          />
          <button type="submit" className="form-add-btn" style={{ flex: 1 }}>
            ＋ 支出項目を追加
          </button>
        </div>
      </form>
    </div>
  );
};

export default ExpenseList;

import { useState, useMemo } from 'react';
