  { id: 'item-5', name: '日用品', amount: 12000, color: '#10b981', icon: '🧴' },
  { id: 'item-6', name: '娯楽交際費', amount: 25000, color: '#ec4899', icon: '🎉' },
  { id: 'item-7', name: '医療費', amount: 6200, color: '#ef4444', icon: '💊' },
  { id: 'item-8', name: 'その他', amount: 9500, color: '#64748b', icon: '📦' },
];

const App = () => {
  const [items, setItems] = useState<ExpenseItem[]>(INITIAL_EXPENSES);
  const [selectedId, setSelectedId] = useState<string | null>('item-1');

  const totalAmount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.amount, 0);
  }, [items]);

  const selectedItem = useMemo(() => {
    if (!selectedId) return null;
    return items.find((item) => item.id === selectedId) || null;
  }, [items, selectedId]);

  const handleSelectItem = (id: string) => {
    setSelectedId((prev) => (prev === id ? null : id));
  };

  const handleUpdateAmount = (id: string, newAmount: number) => {
    setItems((prevItems) =>
      prevItems.map((item) =>
        item.id === id ? { ...item, amount: newAmount } : item
      )
    );
  };

  const handleAddItem = (newItem: Omit<ExpenseItem, 'id'>) => {
    const uniqueId = `item-${Date.now()}`;
    const itemWithId: ExpenseItem = {
      ...newItem,
      id: uniqueId,
    };
    setItems((prev) => [...prev, itemWithId]);
    setSelectedId(uniqueId);
  };

  const handleDeleteItem = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="app-title">家計簿支出ダッシュボード</h1>
        <p className="app-subtitle">
          円グラフのセグメントまたはリストの項目をクリックして詳細を確認・編集できます
        </p>
      </header>

      <section className="total-banner">
        <div className="total-label">今月の総支出合計</div>
        <div className="total-value">¥{totalAmount.toLocaleString()}</div>
      </section>

      <main className="dashboard-grid">
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <ExpensePieChart
            items={items}
            selectedId={selectedId}
            onSelectItem={handleSelectItem}
          />
          {selectedItem && (
            <ExpenseDetail
              selectedItem={selectedItem}
              totalAmount={totalAmount}
              onUpdateAmount={handleUpdateAmount}
              onClose={() => setSelectedId(null)}
            />
          )}
        </div>

        <ExpenseList
          items={items}
          selectedId={selectedId}
          totalAmount={totalAmount}
          onSelectItem={handleSelectItem}
          onAddItem={handleAddItem}
          onDeleteItem={handleDeleteItem}
        />
      </main>
    </div>
  );
};

export default App;
